import 'package:flutter/material.dart'; import '../models/chatbot_models.dart'; import 'conversation_list_item.dart';
class ConversationDrawer extends StatelessWidget { const ConversationDrawer({super.key, required this.conversations, required this.selectedId, required this.onOpen, required this.onRename, required this.onDelete, required this.onNew}); final List<ConversationSummary> conversations; final String? selectedId; final ValueChanged<ConversationSummary> onOpen; final ValueChanged<ConversationSummary> onRename; final ValueChanged<ConversationSummary> onDelete; final VoidCallback onNew;
@override Widget build(BuildContext context) => Drawer(child: SafeArea(child: Column(children: [ListTile(title: const Text('Conversations'), trailing: IconButton(onPressed: onNew, tooltip: 'New conversation', icon: const Icon(Icons.add_rounded))), Expanded(child: ListView(children: [for (final item in conversations) ConversationListItem(conversation: item, selected: item.id == selectedId, onOpen: () => onOpen(item), onRename: () => onRename(item), onDelete: () => onDelete(item))]))]))); }
